head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.onpageload = function () {
};



// 컴포넌트 루트 엘리먼트의 inline style 중 width / height 만 추출한다.
scwin.getInlineSize = function (objComp) {
    let el = objComp.render;
    if (el == null) {
        return "(없음)";
    }
    return "width:" + (el.style.width == "" ? "(미지정)" : el.style.width)
         + " / height:" + (el.style.height == "" ? "(미지정)" : el.style.height);
};



// 컴포넌트 루트 엘리먼트의 실제 렌더 크기를 조회한다.
scwin.getClientSize = function (objComp) {
    let el = objComp.render;
    if (el == null) {
        return "(없음)";
    }
    return el.clientWidth + " / " + el.clientHeight;
};



// roundRectangle 내부에 그려진 SVG 도형(rect) 의 크기를 조회한다.
scwin.getGraphicSize = function (objComp) {
    let el = objComp.render == null ? null : objComp.render.querySelector("rect");
    if (el == null) {
        return "(없음)";
    }
    return el.getAttribute("width") + " / " + el.getAttribute("height");
};



// 현재 상태를 A(roundRectangle) / B(button) 비교 형태로 출력한다.
scwin.printState = function (strTitle) {
    scwin.setReturnValue(strTitle);
    scwin.setReturnValue("  [A] roundRectangle getSize    : " + target1.getSize("width") + " / " + target1.getSize("height"));
    scwin.setReturnValue("  [A] roundRectangle 루트 style : " + scwin.getInlineSize(target1));
    scwin.setReturnValue("  [A] roundRectangle 실제 크기  : " + scwin.getClientSize(target1));
    scwin.setReturnValue("  [A] roundRectangle 내부 SVG   : " + scwin.getGraphicSize(target1));
    scwin.setReturnValue("  [B] button         getSize    : " + target2.getSize("width") + " / " + target2.getSize("height"));
    scwin.setReturnValue("  [B] button         루트 style : " + scwin.getInlineSize(target2));
    scwin.setReturnValue("");
};



scwin.btn_init_onclick = function (e) {
    scwin.printState("[초기 상태 / style 로 지정한 100 x 100]");
};



scwin.btn_setSize_normal_onclick = function (e) {
    target1.setSize(50, 60);
    target2.setSize(50, 60);
    scwin.printState("[setSize(50, 60) 호출 후]");
};



scwin.btn_setSize_zero_onclick = function (e) {
    target1.setSize(0, 0);
    target2.setSize(0, 0);
    scwin.printState("[setSize(0, 0) 호출 후]");
};



scwin.btn_setSize_negative_onclick = function (e) {
    target1.setSize(-1, null);
    target2.setSize(-1, null);
    scwin.printState("[setSize(-1, null) 호출 후]");
};



scwin.btn_setSize_restore_onclick = function (e) {
    target1.setSize(100, 100);
    target2.setSize(100, 100);
    scwin.printState("[setSize(100, 100) 호출 후]");
};
